module pin_closed() {
    // stepped octagonal axle (flats top/bottom), captive caps both ends
    extrude_yz(oct_pts(pin_r), pin_x0, pin_len, hinge_y, hinge_z);
    extrude_yz(oct_pts(cap_r), pin_x0, 3, hinge_y, hinge_z);
    extrude_yz(oct_pts(cap_r), pin_x0 + pin_len - 3, 3, hinge_y, hinge_z);
}

arguments.new:
module pin_closed() {
    // plain octagonal axle (flats top/bottom), ends protrude past the outer knuckles
    extrude_yz(oct_pts(pin_r), pin_x0, pin_len, hinge_y, hinge_z);
}
